package org.cgse.core;
import java.math.BigInteger;import java.util.*;
public class GubDeficitProbe{
 static BigInteger b(long v){return BigInteger.valueOf(v);}static boolean pass(ExactLinearProgram.Constraint row,BigInteger[] x){BigInteger sum=BigInteger.ZERO;for(var e:row.terms().entrySet())sum=sum.add(e.getValue().multiply(x[e.getKey()]));return sum.compareTo(row.upper())<=0;}
 public static void main(String[] args){Random rnd=new Random(8197877);long cuts=0,feasible=0;for(int test=0;test<2000;test++){int n=4+rnd.nextInt(7);BigInteger[] lo=new BigInteger[n],hi=new BigInteger[n],plant=new BigInteger[n];ExactRational[] point=new ExactRational[n];int previous=0;for(int i=0;i<n;i++){lo[i]=b(rnd.nextInt(5)-2);hi[i]=lo[i].add(BigInteger.ONE);int q=rnd.nextInt(i%2==0?5:5-previous);point[i]=ExactRational.of(lo[i]).add(new ExactRational(b(q),b(4)));previous=q;plant[i]=lo[i].add(b(i%2==0?1:0));}List<ExactLinearProgram.Constraint> rows=new ArrayList<>();for(int start=0;start<n-1;start+=2){Map<Integer,BigInteger> terms=new TreeMap<>();terms.put(start,BigInteger.ONE);terms.put(start+1,BigInteger.ONE);rows.add(new ExactLinearProgram.Constraint(terms,lo[start].add(lo[start+1]).add(BigInteger.ONE)));}for(int r=0;r<1+rnd.nextInt(4);r++){Map<Integer,BigInteger> terms=new TreeMap<>();BigInteger rhs=b(rnd.nextInt(7));for(int i=0;i<n;i++){BigInteger w=b(rnd.nextInt(25)-12);if(w.signum()!=0)terms.put(i,w);rhs=rhs.add(w.multiply(plant[i]));}rows.add(new ExactLinearProgram.Constraint(terms,rhs));}if(test%3==0){BigInteger scale=BigInteger.TEN.pow(40);var scaled=new ArrayList<ExactLinearProgram.Constraint>();for(var row:rows){Map<Integer,BigInteger> t=new TreeMap<>();row.terms().forEach((k,v)->t.put(k,v.multiply(scale)));scaled.add(new ExactLinearProgram.Constraint(t,row.upper().multiply(scale)));}rows=scaled;}PlanningBudget budget=new PlanningBudget(0,20000000,64L<<20,()->false,()->0L);var generated=CountGubDeficitPrototype.separate(rows,lo,hi,point,budget,131072);cuts+=generated.size();for(int mask=0;mask<(1<<n);mask++){BigInteger[] x=lo.clone();for(int i=0;i<n;i++)if((mask&(1<<i))!=0)x[i]=hi[i];if(rows.stream().anyMatch(r->!pass(r,x)))continue;feasible++;for(var cut:generated)if(!pass(cut,x))throw new AssertionError("test="+test+" cut="+cut+" witness="+Arrays.toString(x));}if(budget.reservedBytes()!=0)throw new AssertionError("leak");}System.out.println("GubDeficitProbe models=2000 cuts="+cuts+" feasiblePoints="+feasible+" invalid=0 leaks=0");}
}
